def initialize_tags(apps,schema_editor):
    Tag=apps.get_model('tasks','PersonalTag')
    Card=apps.get_model('tasks','PersonalCard')
    for name in ['일반 업무','유지보수','정기 점검','회의','자료 정리','아이디어','학습','기타']:
        Tag.objects.get_or_create(owner_id=None,name=name)
    for card in Card.objects.exclude(label='').select_related('column__board').iterator():
        name=card.label.strip()
        if not name:continue
        tag=Tag.objects.filter(owner_id=None,name=name).first()
        if not tag:tag,_=Tag.objects.get_or_create(owner_id=card.column.board.owner_id,name=name)
        card.tags.add(tag)


